int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    int error;
    struct sk_buff *skb;
    size_t copied = 0;

    if (sock->type == SOCK_DGRAM) {
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;

        if (flags & MSG_OOB) {
            error = skb_pull_oob(skb, &copied);
            if (error)
                return error;
        } else {
            copied = min(skb->len, len);
            if (skb_copy_datagram_msg(skb, 0, msg, 0, copied))
                return -EFAULT;
        }
        skb_free(skb);
    } else if (sock->type == SOCK_STREAM) {
        while (copied < len) {
            skb = skb_dequeue(&sock->sk->sk_receive_queue);
            if (!skb)
                break;

            size_t copy_len = min(skb->len, len - copied);
            if (flags & MSG_PEEK)
                copy_len = 0;

            if (skb_copy_datagram_msg(skb, 0, msg, copied, copy_len))
                return -EFAULT;

            copied += copy_len;
            if (copy_len < skb->len)
                skb_pull(skb, copy_len);
            else
                skb_free(skb);
        }
        if (copied == 0)
            return -EAGAIN;
    } else {
        return -EINVAL;
    }

    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (sock->sk == NULL)
        return -ENOTCONN;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    while (len > 0 && skb) {
        int copy = min_t(int, len, skb->len);

        if (skb->len > copy) {
            if (flags & MSG_TRUNC)
                copy = skb->len;
            else
                skb = skb_clone(skb, GFP_KERNEL);
        }

        if (!skb)
            break;

        err = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, copy);
        if (err)
            break;

        copied += copy;
        len -= copy;
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
    }

    return copied ? copied : err;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    struct sock *sk = sock->sk;
    int error;
    int data_len;

    if (sk->sk_state == TCP_LISTEN)
        return -ENOTCONN;

    if (flags & MSG_OOB)
        return -EOPNOTSUPP;

    error = skb_recv_datagram(sk, flags, &data_len);
    if (error < 0)
        return error;

    if (data_len > len) {
        if (flags & MSG_TRUNC)
            data_len = len;
        else
            error = -EMSGSIZE;
    }

    if (copy_to_iter(skb_data, data_len, msg->msg_iter) != data_len)
        return -EFAULT;

    return data_len;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (sock->state == SS_DISCONNECTED && !(flags & MSG_PEEK)) {
        return -ENOTCONN;
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (flags & MSG_OOB) {
        // Process out-of-band data
        if (skb->len < len) {
            copied = skb->len;
        } else {
            copied = len;
        }
        memcpy(msg->msg_name, skb->data, copied);
    } else {
        if (skb->len < len) {
            copied = skb->len;
        } else {
            copied = len;
        }

        if (copied < skb->len) {
            msg->msg_flags |= MSG_TRUNC;
        }

        err = memcpy_toiovec(msg->msg_iov, skb->data, copied);
        if (err) {
            skb_queue_head(&sock->sk->sk_receive_queue, skb);
            return err;
        }
    }

    sock->sk->sk_data_processed += copied;
    kfree_skb(skb);

    return copied;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags)
{
    struct sock *sk = sock->sk;
    ssize_t copied = 0;
    int err = 0;

    if (sk->sk_state == TCP_LISTEN) {
        return -EINVAL;
    }

    if (flags & MSG_OOB) {
        copied = sock_recv_dgram(struct sock *sk, struct msghdr *msg, size_t len, int flags);
        if (copied < 0)
            return copied;
        return copied;
    }

    while (len) {
        struct sk_buff *skb;

        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb) {
            if (copied)
                break;
            return -EAGAIN;
        }

        if (skb->len == 0) {
            kfree_skb(skb);
            continue;
        }

        if (skb->len > len) {
            if (!(flags & MSG_TRUNC)) {
                if (copied == 0)
                    return -EMSGSIZE;
                break;
            }
            copied += len;
            kfree_skb(skb);
            break;
        }

        copied += skb->len;
        len -= skb->len;

        if (skb_copy_datagram_to(skb, 0, msg->msg_iov, 0, skb->len)) {
            kfree_skb(skb);
            return -EFAULT;
        }

        kfree_skb(skb);
    }

    return copied;
}
